    // Apply acceleration/deceleration curve
    player.position.x += horizontalSpeed;

    // Clamp to screen bounds with soft boundary
    const bound = SCREEN_WIDTH / 2 - PLAYER_RADIUS;
    player.position.x = Math.max(-bound, Math.min(bound, player.position.x));
};

// Input mapping: WASD + Gamepad API unified controller
const inputMapping = {
    keyboard: { left: 'ArrowLeft', right: 'ArrowRight', fire: 'Space' },
    gamepad: { left: 0, right: 1, fire: 2 } // Button indices
};
```

### Invader Formation Mechanics

```javascript
// Grid formation: 5 rows × 11 columns = 55 invaders total
const FORMATION_CONFIG = {
    rows: 5,
    cols: 11,
    spacingX: 3.0,      // Horizontal spacing between invaders
    spacingY: 2.5,     // Vertical spacing between rows
    baseSpeed: 0.8,    // Initial horizontal movement speed
};

// Formation state machine
const formationUpdate = (formation, dt) => {
    const direction = formation.direction;

    // Update all invaders in formation
    formation.invaders.forEach(invader => {
        invader.position.x += direction * formation.speed * dt;

        // Edge detection: trigger downward movement
        if (Math.abs(invader.position.x) > EDGE_THRESHOLD) {
            formation.triggerDirectionChange();
        }
    });
};

// Speed progression based on remaining invaders
const calculateSpeedMultiplier = (remaining, initialCount) => {
    const ratio = remaining / initialCount;
    return 1.0 + (1 - ratio) * 2.5; // Up to 3.5x speed increase
};
```

### Projectile Physics Engine

```javascript
// Projectile trajectory calculation
const projectileUpdate = (projectile, dt) => {
    const velocity = projectile.velocity.clone().multiplyScalar(dt);

    // Apply gravity for invader projectiles only
    if (projectile.type === 'invader') {
        velocity.y -= GRAVITY * dt;
    }

    // Update position with delta time
    projectile.position.add(velocity);

    // Lifetime management
    projectile.lifetime -= dt;
    return projectile.lifetime > 0;
};

// Collision detection: Sphere-based intersection
const detectCollision = (sphereA, sphereB) => {
    const distance = sphereA.position.distanceTo(sphereB.position);
    return distance < (sphereA.radius + sphereB.radius);
};
```

### Scoring System Architecture

```javascript
const SCORING_CONFIG = {
    // Base points per enemy type
    enemyPoints: {
        basic: 10,
        medium: 25,
        elite: 50,
        boss: 100
    },

    // Multiplier system for consecutive kills
    comboMultiplier: (kills) => Math.min(kills * 0.5, 3.0),

    // Progressive difficulty scaling
    calculateDifficulty = (level) => {
        return level * 0.1 + 0.5; // 50% base increase per level
    }
};
```

