```javascript
// Centralized particle system with hard 500-particle cap
class ParticleManager {
    constructor(maxParticles = 500) {
        this.maxParticles = maxParticles;
        this.activeParticles = [];
        this.particlePool = new ObjectPool(Particle, maxParticles);

        // Particle types and configurations
        this.particleTypes = {
            EXPLOSION: { color: [1.0, 0.5, 0.2], lifetime: 0.8 },
            SPARKS: { color: [1.0, 1.0, 0.3], lifetime: 0.4 },
            SMOKE: { color: [0.3, 0.3, 0.3], lifetime: 1.2 }
        };
    }

    emitParticle(type, position, count) {
        if (this.activeParticles.length + count > this.maxParticles) return;

        for (let i = 0; i < count; i++) {
            const particle = this.particlePool.acquire();

            // Configure particle based on type
            particle.configure(this.particleTypes[type], position);

            // Randomize velocity for natural spread
            particle.velocity.setRandomDirection(2.0, Math.PI / 4);

            this.activeParticles.push(particle);
        }
    }

    update(dt) {
        // Update and remove dead particles
        this.activeParticles = this.activeParticles.filter(p => {
            p.update(dt);
            if (p.lifetime <= 0) {
                this.particlePool.release(p);
                return false;
            }
            return true;
        });
    }
}
